<script>
(()=>{const q=document.getElementById('permission-search');if(!q)return;q.addEventListener('input',()=>{const term=q.value.trim().toLowerCase();document.querySelectorAll('.permission-group').forEach(group=>{let visible=0;group.querySelectorAll('.permission-item').forEach(row=>{const match=!term||row.dataset.permission.includes(term);row.style.display=match?'flex':'none';if(match)visible++});group.style.display=visible?'block':'none';group.open=!!(term&&visible);});});})();
</script>
